from __future__ import annotations
STYLE='''<style id="predibeacon-home-v2-style">.hero-v2{display:grid;grid-template-columns:minmax(0,.9fr) minmax(430px,1.1fr);gap:2rem;align-items:center;padding:3.2rem 0 2rem}.hero-v2 h1{font-size:clamp(2.8rem,6vw,5rem);line-height:.98;margin:.5rem 0 1.2rem}.hero-v2 h1 em{font-style:normal;color:var(--accent)}.hero-copy{color:var(--muted);font-size:1.08rem;line-height:1.65}.trust-row,.quick-filters{display:flex;gap:.55rem;flex-wrap:wrap;margin-top:1rem}.trust-pill,.quick-filter{border:1px solid var(--line);border-radius:999px;padding:.55rem .8rem;font-size:.8rem;font-weight:800}.venue-hub{display:grid;grid-template-columns:1fr .65fr 1fr;gap:.8rem;border:1px solid var(--line);border-radius:20px;padding:1rem;background:linear-gradient(135deg,rgba(139,233,199,.04),rgba(31,94,255,.04))}.venue-card{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:16px;padding:1.15rem;text-decoration:none;background:rgba(17,24,39,.72);transition:border-color .2s,transform .2s}.venue-card:hover{border-color:var(--accent);transform:translateY(-2px)}.venue-name{font-size:1.25rem;font-weight:900}.venue-count{font-size:2rem;font-weight:900;margin:.7rem 0}.venue-sub{color:var(--muted);font-size:.82rem}.venue-cta{margin-top:1.2rem;font-weight:900;color:var(--accent)}.poly .venue-cta{color:#6ea1ff}.beacon-core{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-width:0}.beacon-graphic{position:relative;width:76px;height:96px;margin-bottom:.7rem}.beacon-graphic:before{content:"";position:absolute;left:22px;bottom:0;width:32px;height:70px;background:linear-gradient(180deg,var(--accent),rgba(139,233,199,.22));clip-path:polygon(36% 0,64% 0,100% 100%,0 100%);border-radius:4px}.beacon-graphic:after{content:"";position:absolute;left:18px;top:8px;width:40px;height:24px;border:2px solid var(--accent);border-radius:8px;background:var(--panel);box-shadow:0 0 22px rgba(139,233,199,.38)}.beacon-light{position:absolute;left:34px;top:15px;width:9px;height:9px;border-radius:50%;background:#fff;box-shadow:0 0 18px 8px rgba(139,233,199,.35)}.beacon-light:before,.beacon-light:after{content:"";position:absolute;top:3px;width:55px;height:3px;background:linear-gradient(90deg,transparent,rgba(139,233,199,.45))}.beacon-light:before{right:7px;transform:rotate(10deg);transform-origin:right}.beacon-light:after{left:7px;transform:rotate(-10deg);transform-origin:left}.beacon-core small{color:var(--muted);margin-top:.4rem}.change-strip{display:flex;gap:.6rem;overflow:auto;border:1px solid var(--line);border-radius:16px;padding:.7rem;margin-bottom:2rem}.change-title{min-width:145px;padding:.65rem;font-weight:900}.change-title small{display:block;color:var(--muted);font-weight:500}.change-item{min-width:190px;border-left:1px solid var(--line);padding:.65rem;font-size:.84rem}.quick-filter{background:transparent;color:var(--text);font:inherit;min-height:44px}.quick-filter[aria-pressed=true]{border-color:var(--accent);color:var(--accent)}.freshness{display:none}.controls label:has(#venue){display:none}.controls{grid-template-columns:1fr}.discovery-explainer{display:none}.grid{display:block;padding-bottom:3rem}.card[data-home-row="ready"]{display:grid;grid-template-columns:minmax(250px,1.35fr) minmax(120px,.55fr) minmax(150px,.72fr) minmax(230px,1fr) minmax(150px,.65fr);grid-template-areas:"market prediction facts venue actions";align-items:center;gap:1rem;padding:1rem 1.1rem;margin-bottom:.7rem;min-height:132px}.market-summary{grid-area:market;min-width:0}.market-summary h3{margin:.55rem 0;font-size:1rem;line-height:1.35}.market-summary .insight{min-height:0;margin:.35rem 0 0;font-size:.78rem}.prediction-summary{grid-area:prediction}.prediction-summary .prob{font-size:2rem;margin:0}.prediction-summary .move{font-size:.78rem;margin-top:.25rem}.card[data-home-row="ready"] .facts{grid-area:facts;grid-template-columns:1fr;gap:.35rem;margin:0}.card[data-home-row="ready"] .fact{padding-top:.35rem}.card[data-home-row="ready"] .platform-availability{grid-area:venue;margin:0;min-height:86px}.card[data-home-row="ready"] .actions{grid-area:actions;grid-template-columns:1fr;gap:.5rem;margin:0}.card[data-home-row="ready"] .rank{top:.65rem;right:.75rem;font-size:.75rem}@media(max-width:1050px){.card[data-home-row="ready"]{display:block;min-height:0}.market-summary h3{font-size:1.05rem}.prediction-summary .prob{margin-top:1rem}.card[data-home-row="ready"] .facts{grid-template-columns:repeat(3,1fr);margin-top:.9rem}.card[data-home-row="ready"] .platform-availability{margin-top:.8rem}.card[data-home-row="ready"] .actions{grid-template-columns:1fr auto;margin-top:1rem}}@media(max-width:900px){.hero-v2{grid-template-columns:1fr}.venue-hub{grid-template-columns:1fr 1fr}.beacon-core{grid-column:1/-1;grid-row:1;padding:1rem}.venue-card:hover{transform:none}}@media(max-width:560px){.venue-hub{grid-template-columns:1fr}.beacon-core{grid-column:auto}.hero-v2 h1{font-size:2.7rem}.card[data-home-row="ready"] .facts,.card[data-home-row="ready"] .actions{grid-template-columns:1fr}}</style>'''
SCRIPT=r'''<script id="predibeacon-home-v2-script">(()=>{const hero=document.querySelector('.hero');if(!hero)return;let activeMode='trending';hero.className='hero-v2 wrap';hero.innerHTML=`<div><div class="eyebrow">INTELIGÊNCIA DE MERCADO EM TEMPO REAL</div><h1>Descubra o que está movimentando os <em>mercados de previsão.</em></h1><p class="hero-copy">Kalshi + Polymarket, priorizados, comparados e explicados em um só lugar.</p><div class="trust-row"><span class="trust-pill">✓ Independente</span><span class="trust-pill">✓ Transparente</span><span class="trust-pill">◎ Focado no que importa</span></div></div><div class="venue-hub"><a class="venue-card" href="#markets" data-venue-link="kalshi"><span class="venue-name">Kalshi</span><span class="venue-count" id="v2-k-count">—</span><span class="venue-sub">mercados monitorados</span><span class="venue-cta">Explorar Kalshi →</span></a><div class="beacon-core"><div class="beacon-graphic" aria-hidden="true"><span class="beacon-light"></span></div><strong>PREDIBEACON</strong><small>Nós analisamos.<br>Você decide.</small></div><a class="venue-card poly" href="#markets" data-venue-link="polymarket"><span class="venue-name">Polymarket</span><span class="venue-count" id="v2-p-count">—</span><span class="venue-sub">mercados monitorados</span><span class="venue-cta">Explorar Polymarket →</span></a></div>`;const markets=document.querySelector('#markets'),controls=markets?.querySelector('.controls');if(controls){const q=document.createElement('div');q.className='quick-filters';q.innerHTML='<button class="quick-filter" aria-pressed="true" data-q="trending">Para você</button><button class="quick-filter" aria-pressed="false" data-q="movers">Em movimento</button><button class="quick-filter" aria-pressed="false" data-q="volume">Mais ativos</button><button class="quick-filter" aria-pressed="false" data-q="closing">Terminando em breve</button>';controls.insertAdjacentElement('beforebegin',q)}const venue=document.querySelector('#venue'),sort=document.querySelector('#sort'),gridNode=document.querySelector('#grid'),countNode=document.querySelector('#count'),stateNode=document.querySelector('#state');function structureCards(){if(!gridNode)return;for(const c of gridNode.querySelectorAll('.card')){if(c.dataset.homeRow==='ready')continue;const meta=c.querySelector('.meta'),title=c.querySelector('h3'),insight=c.querySelector('.insight'),prob=c.querySelector('.prob'),move=c.querySelector('.move');if(!meta||!title||!prob)continue;const market=document.createElement('div');market.className='market-summary';c.insertBefore(market,meta);market.append(meta,title);if(insight)market.append(insight);const prediction=document.createElement('div');prediction.className='prediction-summary';const facts=c.querySelector('.facts');c.insertBefore(prediction,facts||c.querySelector('.actions'));prediction.append(prob);if(move)prediction.append(move);c.dataset.homeRow='ready'}}if(gridNode){new MutationObserver(structureCards).observe(gridNode,{childList:true});structureCards()}async function loadClosing(){if(!gridNode)return;stateNode.hidden=false;gridNode.innerHTML='';const q=new URLSearchParams({limit:'100'});if(venue?.value)q.set('venue',venue.value);try{const r=await fetch('/api/v1/markets/closing-soon?'+q);if(!r.ok)throw 0;const data=await r.json();gridNode.innerHTML=data.map(card).join('');countNode.textContent=data.length+' market'+(data.length===1?'':'s');stateNode.textContent=data.length?'':'Nenhum mercado com prazo conhecido está fechando em breve.';stateNode.hidden=!!data.length}catch{countNode.textContent='Indisponível';stateNode.className='error';stateNode.textContent='O ranking por prazo está temporariamente indisponível.'}}document.querySelectorAll('[data-venue-link]').forEach(a=>a.addEventListener('click',()=>{venue.value=a.dataset.venueLink;if(activeMode==='closing')loadClosing();else venue.dispatchEvent(new Event('change',{bubbles:true}))}));document.querySelectorAll('.quick-filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.quick-filter').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));activeMode=b.dataset.q;if(activeMode==='closing')loadClosing();else{sort.value=activeMode;sort.dispatchEvent(new Event('change',{bubbles:true}))}}));fetch('/api/v1/status').then(r=>{if(!r.ok)throw 0;return r.json()}).then(d=>{document.querySelector('#v2-k-count').textContent=d.venue_market_counts?.kalshi||'—';document.querySelector('#v2-p-count').textContent=d.venue_market_counts?.polymarket||'—'}).catch(()=>{});const strip=document.createElement('div');strip.className='change-strip wrap';strip.innerHTML='<div class="change-title">⚡ O que está mudando<small>Dados atuais</small></div><div class="change-item" id="v2-c1">Carregando movimentos…</div><div class="change-item" id="v2-c2">Carregando atividade…</div><div class="change-item" id="v2-c3">Verificando divergências…</div>';hero.insertAdjacentElement('afterend',strip);Promise.all([fetch('/api/v1/markets?sort=movers&limit=1').then(r=>{if(!r.ok)throw 0;return r.json()}),fetch('/api/v1/markets?sort=volume&limit=1').then(r=>{if(!r.ok)throw 0;return r.json()}),fetch('/api/v1/compare/pairs?limit=12&candidate_limit=24').then(r=>{if(!r.ok)throw 0;return r.json()})]).then(([m,v,p])=>{document.querySelector('#v2-c1').textContent=m[0]?`${m[0].title} · ${m[0].probability_change==null?'movimento indisponível':(m[0].probability_change>=0?'↑ ':'↓ ')+Math.abs(m[0].probability_change*100).toFixed(1)+' pts'}`:'Sem movimento relevante';document.querySelector('#v2-c2').textContent=v[0]?`Mais ativo: ${v[0].title}`:'Atividade indisponível';const x=(p.pairs||[]).filter(x=>x.verification?.equivalent_contracts&&x.left.probability!=null&&x.right.probability!=null).sort((a,b)=>Math.abs(b.left.probability-b.right.probability)-Math.abs(a.left.probability-a.right.probability))[0];document.querySelector('#v2-c3').textContent=x?`Maior divergência verificada: ${(Math.abs(x.left.probability-x.right.probability)*100).toFixed(1)} pts`:'Nenhuma divergência verificada agora'}).catch(()=>{})})();</script>'''
def enhance_home_v2(html:str)->str:
    if 'id="predibeacon-home-v2-script"' in html:return html
    out=html.replace('</head>',STYLE+'</head>',1)
    return out.replace('</body>',SCRIPT+'</body>',1)
